  rm record;
  d date;
  h integer;
  aid uuid;
  st uuid;
  k text;
  notes constant text[] := array['Residents asked for more Gershwin next week.', 'Two residents sang along on the second half; one requested a polka.', 'Good conversation after the program about favorite radio shows.', 'Room was set up late; started ten minutes behind.', 'A resident played the hand drum with us for the last piece.', 'Several family members joined today.', 'Residents voted on next month''s theme: Broadway.', 'Quiet group today; the call-and-response piece went well.', null, null];
  anotes constant text[] := array['Listened to big-band records together and talked about dance halls.', 'Short violin lesson; wants to try again next week.', 'Played requests at the piano in the lounge.', 'Talked about the songs from the Tuesday program.', 'Learned a new folk tune together.', 'Shared photos of the ensemble''s instruments and answered questions.'];
